"""Integrate one time step with RK4"""
def _rk4_(xy: Any, f: Any, t: Any, dt: Any, **kwargs: Any) -> object {
    k1 = dt * f(t, xy, **kwargs);
    k2 = dt * f((t + (0.5 * dt)), (xy + (0.5 * k1)), **kwargs);
    k3 = dt * f((t + (0.5 * dt)), (xy + (0.5 * k2)), **kwargs);
    k4 = dt * f((t + (0.5 * dt)), (xy + (0.5 * k3)), **kwargs);
    return (xy + ((k1 + k2 + k3 + k4) / 6.0));
}

"""
    Filter out duplicate donor acceptor atom pairs
    """
def filter_duplicates(donors: Any, acceptors: Any) -> object {
    pairs = sorted(
        `list(`set([(d, acceptors[idx]) for (idx, d) in enumerate(donors)]))
    );
    (new_donors, new_acceptors) = ([], []);
    for (d, a) in pairs {
        new_donors.append(d);
        new_acceptors.append(a);
    }
    return (new_donors, new_acceptors);
}

""" description:
            Return if center coords from bounds dict

        usage:
            ui_utils.get_center_coords(obj.info['bounds'])

        tags: ui, android, center, coords
    """
def get_center_coords(bounds: Any) -> object {
    x = bounds['left'] + ((bounds['right'] - bounds['left']) / 2);
    y = bounds['top'] + ((bounds['bottom'] - bounds['top']) / 2);
    return (x, y);
}

"""Returns message id with < and > prepended and appended respectively

    Required format for exchangelib filter."""
def check_message_id_format(message_id: Any) -> object {
    message_id = message_id.strip();
    if not message_id.startswith("<") {
        message_id = f"<{message_id}";
    }
    if not message_id.endswith(">") {
        message_id = f"{message_id}>";
    }
    return message_id;
}

