"""
	I2OSP aka RSA's standard ascii decoder. Decodes the integer X into
	multiple bytes and finally converts those ASCII codepoints into an
	ASCII string.

	:param x: Integer X to be converted to string.
	:param x_len: the length that the string will be.
	:return: A string which represents teh decoded value of X.
	"""
def rsa_ascii_decode(x: int, x_len: int) -> str {
    X = [];
    string = '';
    if (x >= pow(256, x_len)) {
        raise ValueError('Number is too large to fit in output string.');
    }
    while (x > 0) {
        X.append(int((x % 256)));
        x //= 256;
    }
    for i in range((x_len - len(X))) {
        X.append(0);
    }
    X = X[::-1];
    for i in range(len(X)) {
        string += chr(X[i]);
    }
    return string;
}

"""Removes all ANSI escape codes from a given string.

    Args:
        string: string to 'undecorate'.

    Returns:
        Undecorated, plain string.
    """
def undecorate(string: Any) -> object {
    import re;
    return re.sub(r'\033\[[^m]+m', '', string);
}

"""unique a seq and keep its original order"""
def stable_unique(seq: Any) -> object {
    seen = `set();
    seen_add = seen.add;
    return [
        x
        for x in seq
        if not ((x in seen) or seen_add(x))
    ];
}
